import { mkdir, readFile, writeFile } from 'node:fs/promises';
import { dirname, join, resolve, sep } from 'node:path';
import { AwsClient } from 'aws4fetch';
import type { Config } from '../config.js';

/** Where uploaded documents live. Keys are generated by the server (`documents/<id>/<sha>`), never by users. */
export interface FileStore {
  put(key: string, bytes: Uint8Array, contentType: string): Promise<void>;
  get(key: string): Promise<Uint8Array | null>;
}

const SAFE_KEY = /^[a-z0-9][a-z0-9/_.-]*$/i;

function assertSafeKey(key: string): void {
  if (!SAFE_KEY.test(key) || key.includes('..')) throw new Error('Invalid storage key');
}

export function localFileStore(dir: string): FileStore {
  const root = resolve(dir);
  const pathFor = (key: string) => {
    assertSafeKey(key);
    const path = resolve(join(root, key));
    if (!path.startsWith(root + sep)) throw new Error('Invalid storage key');
    return path;
  };
  return {
    async put(key, bytes) {
      const path = pathFor(key);
      await mkdir(dirname(path), { recursive: true });
      await writeFile(path, bytes);
    },
    async get(key) {
      try {
        return new Uint8Array(await readFile(pathFor(key)));
      } catch (error) {
        if ((error as NodeJS.ErrnoException).code === 'ENOENT') return null;
        throw error;
      }
    },
  };
}

/** Cloudflare R2 through its S3-compatible API, signed with SigV4. */
export function r2FileStore(options: {
  accountId: string;
  accessKeyId: string;
  secretAccessKey: string;
  bucket: string;
}): FileStore {
  const client = new AwsClient({
    accessKeyId: options.accessKeyId,
    secretAccessKey: options.secretAccessKey,
    service: 's3',
    region: 'auto',
  });
  const endpoint = `https://${options.accountId}.r2.cloudflarestorage.com/${options.bucket}`;
  const urlFor = (key: string) => {
    assertSafeKey(key);
    return `${endpoint}/${key.split('/').map(encodeURIComponent).join('/')}`;
  };
  return {
    async put(key, bytes, contentType) {
      const res = await client.fetch(urlFor(key), {
        method: 'PUT',
        body: bytes,
        headers: { 'content-type': contentType },
      });
      if (!res.ok) throw new Error(`R2 upload failed (${res.status})`);
    },
    async get(key) {
      const res = await client.fetch(urlFor(key));
      if (res.status === 404) return null;
      if (!res.ok) throw new Error(`R2 download failed (${res.status})`);
      return new Uint8Array(await res.arrayBuffer());
    },
  };
}

export function memoryFileStore(): FileStore {
  const files = new Map<string, Uint8Array>();
  return {
    async put(key, bytes) {
      assertSafeKey(key);
      files.set(key, bytes);
    },
    async get(key) {
      return files.get(key) ?? null;
    },
  };
}

export function createFileStore(config: Config): FileStore {
  return config.storage.kind === 'r2' ? r2FileStore(config.storage) : localFileStore(config.storage.dir);
}
